def _cost_on(UserCost, user_id, on_date):
    """Inline copy of UserCost.cost_on (migrations can't call model methods)."""
    dated = (
        UserCost.objects.filter(user_id=user_id, effective_from__lte=on_date)
        .order_by("-effective_from")
        .first()
    )
    if dated is not None:
        return dated.cost_per_hour
    undated = (
        UserCost.objects.filter(user_id=user_id, effective_from__isnull=True)
        .order_by("-pk")
        .first()
    )
    return undated.cost_per_hour if undated is not None else None


def backfill_draw_money(apps, schema_editor):
    """Value existing hour-only draws at the LCR in force when they were made
    (falling back to the latest rate); draws for users with no LCR at all
    stay at 0 and are reported."""
    import datetime

    SupportBudgetDraw = apps.get_model("jobtracker", "SupportBudgetDraw")
    UserCost = apps.get_model("chaotica_utils", "UserCost")
    unpriced = 0
    for draw in SupportBudgetDraw.objects.select_related("support_role"):
        user_id = draw.support_role.user_id
        on_date = draw.created_at.date() if draw.created_at else datetime.date.today()
        lcr = _cost_on(UserCost, user_id, on_date) or _cost_on(
            UserCost, user_id, datetime.date.max
        )
        if not lcr:
            unpriced += 1
            continue
        draw.lcr_at_draw = lcr
        draw.money_drawn = (draw.hours_drawn * lcr).quantize(Decimal("0.01"))
        draw.save(update_fields=["lcr_at_draw", "money_drawn"])
    if unpriced:
        print(
            "\n  {} support draw(s) have no loaded cost rate and were left at "
            "£0 value.".format(unpriced)
        )


